const keyed = <const Values extends readonly FormatInfo[]>(values: Values) =>
  Object.fromEntries(values.map((value) => [value.id, value])) as {
    readonly [Key in Values[number]['id']]: Extract<Values[number], { readonly id: Key }>;
  };

